'use strict';

/**
 * referral.service — the accrual spine for the marketing referral system
 * (Contract 1 of 4, contract: features/referral-engine).
 *
 * Locked model (founder, 2026-05-31):
 *   A referrer (a partner AGENCY or an INFLUENCER) earns an admin-set % of the
 *   PLATFORM's own revenue generated by an entity they referred (a BRAND or an
 *   INFLUENCER), for a flat 12 months from the referral. The referral amount is
 *   carved from the platform's slice ONLY — it never reduces influencer
 *   earnings, escrow net_to_influencer, or brand net. It accrues only on
 *   CONFIRMED revenue (paid subscription invoice / released escrow tranche /
 *   confirmed follower commission), so refunds/reversals never over-pay.
 *
 *   Attribution (single beneficiary per event):
 *     - BRAND referred      → subscription + protection_fee accrue.
 *     - INFLUENCER referred → public-purchase commission accrues.
 *
 * Idempotency: referral_ledger has unique(source, source_ref_id), so a webhook
 * retry or cron re-run can never double-accrue.
 *
 * Best-effort: accrual must NEVER break the host money path. Callers use either
 *   - accrue(opts)               — opens its own transaction (webhook / cron), or
 *   - accrueWithClient(client,…) — SAVEPOINT-isolated inside a host transaction
 *     (escrow tranche release),
 * both of which swallow+log accrual errors so the underlying payment/credit
 * still commits.
 */

const crypto = require('crypto');
const db = require('../config/db');
const AppError = require('../utils/AppError');

const REFERRAL_WINDOW_MONTHS = 12;

function round2(n) {
  return parseFloat(parseFloat(n).toFixed(2));
}

// ── Code generation / lookup ───────────────────────────────────────────────

/** Human-friendly, collision-resistant code (e.g. "INFLX-7QK4M2"). */
function _newCodeString() {
  const raw = crypto.randomBytes(5).toString('hex').toUpperCase().slice(0, 6);
  return `INFLX-${raw}`;
}

/**
 * Get (or lazily create) the shareable code for a referrer.
 * One code per (referrer_type, referrer_id) — enforced by uniq_referral_code_owner.
 */
async function getOrCreateCode(referrerType, referrerId, client = db) {
  const { rows: existing } = await client.query(
    `SELECT * FROM referral_codes WHERE referrer_type = $1 AND referrer_id = $2`,
    [referrerType, referrerId]
  );
  if (existing[0]) return existing[0];

  // Retry on the (rare) code-collision unique violation.
  for (let attempt = 0; attempt < 5; attempt++) {
    try {
      const { rows } = await client.query(
        `INSERT INTO referral_codes (referrer_type, referrer_id, code)
         VALUES ($1, $2, $3)
         ON CONFLICT (referrer_type, referrer_id) DO UPDATE SET code = referral_codes.code
         RETURNING *`,
        [referrerType, referrerId, _newCodeString()]
      );
      return rows[0];
    } catch (err) {
      if (err.code === '23505' && attempt < 4) continue; // code string collision — retry
      throw err;
    }
  }
  throw new AppError('INTERNAL_ERROR', 'Could not allocate a referral code', 500);
}

async function lookupCode(code, client = db) {
  const { rows } = await client.query(
    `SELECT * FROM referral_codes WHERE code = $1`,
    [code]
  );
  return rows[0] || null;
}

// ── Edge resolution + creation ─────────────────────────────────────────────

/**
 * Resolve the in-window ACTIVE referral edge for a referred entity, if any.
 * Returns the edge row, or null when there is no active in-window referrer.
 */
async function resolveActiveEdge(referredType, referredId, client = db) {
  const { rows } = await client.query(
    `SELECT * FROM referral_edges
      WHERE referred_type = $1
        AND referred_id   = $2
        AND status        = 'active'
        AND now() <= expires_at
      LIMIT 1`,
    [referredType, referredId]
  );
  return rows[0] || null;
}

/**
 * Create a referral edge with the locked guards:
 *   - no self-referral (referrer == referred)
 *   - no circular referral (a reverse active edge already exists)
 *   - first-touch dedup is enforced by the partial unique index
 *     uniq_referral_active_referred (a duplicate active edge → 23505).
 *
 * @param {object} opts
 * @param {'agency'|'influencer'} opts.referrerType
 * @param {string} opts.referrerId
 * @param {'brand'|'influencer'} opts.referredType
 * @param {string} opts.referredId
 * @param {number} opts.pct
 * @param {'signup'|'admin'} opts.source
 * @param {string} [opts.codeId]
 * @param {string} [opts.createdByAdminId]
 * @param {string} [opts.kind='referral']
 */
async function createEdge(opts, client = db) {
  const {
    referrerType, referrerId, referredType, referredId,
    pct, source, codeId = null, createdByAdminId = null, kind = 'referral',
  } = opts;

  if (referrerType == null || referrerId == null || referredType == null || referredId == null) {
    throw new AppError('VALIDATION_ERROR', 'referrer and referred type/id are required', 422);
  }
  if (pct == null || isNaN(parseFloat(pct)) || parseFloat(pct) < 0) {
    throw new AppError('VALIDATION_ERROR', 'pct must be a non-negative number', 422, 'pct');
  }

  // Self-referral guard
  if (referrerType === referredType && referrerId === referredId) {
    throw new AppError('VALIDATION_ERROR', 'A referrer cannot refer themselves', 422);
  }

  // Circular guard: the inverse edge is currently active (A→B while B→A active).
  const inverse = await resolveActiveEdge(referrerType, referrerId, client);
  if (inverse && inverse.referrer_type === referredType && inverse.referrer_id === referredId) {
    throw new AppError('VALIDATION_ERROR', 'Circular referral is not allowed', 422);
  }

  const { rows } = await client.query(
    `INSERT INTO referral_edges
       (referrer_type, referrer_id, referred_type, referred_id, pct, kind,
        status, source, code_id, created_by_admin_id, started_at, expires_at)
     VALUES ($1, $2, $3, $4, $5, $6,
             'active', $7, $8, $9, now(),
             now() + ($10 || ' months')::interval)
     RETURNING *`,
    [
      referrerType, referrerId, referredType, referredId, round2(pct), kind,
      source, codeId, createdByAdminId, String(REFERRAL_WINDOW_MONTHS),
    ]
  );
  return rows[0];
}

// ── Accrual ────────────────────────────────────────────────────────────────

/**
 * Core accrual against a given client (transaction or pool). Resolves the
 * active in-window edge for the referred entity, writes the idempotent ledger
 * row, and — for influencer referrers — credits their wallet inline and marks
 * the row paid. Agency-referrer rows stay 'pending' (agency wallet arrives in
 * Contract 3; no agency referrers can exist before then).
 *
 * @param {object} opts
 * @param {'subscription'|'protection_fee'|'commission'} opts.source
 * @param {string} opts.sourceRefId  subscription_invoices.id / escrow_entries.id / follower_transactions.id
 * @param {'brand'|'influencer'} opts.referredType
 * @param {string} opts.referredId
 * @param {number} opts.baseAmount   the platform's slice for this event (rupees)
 * @returns {Promise<object|null>}   the ledger row written, or null on no-op
 */
async function _accrueOnClient(client, opts) {
  const { source, sourceRefId, referredType, referredId, baseAmount } = opts;

  const edge = await resolveActiveEdge(referredType, referredId, client);
  if (!edge) return null; // no active in-window referrer → silent no-op

  const base = round2(baseAmount);
  const pct = parseFloat(edge.pct);
  const amount = round2(base * pct / 100);

  // Idempotent ledger insert. unique(source, source_ref_id) — a retry/re-run
  // hits the conflict and writes nothing.
  const { rows: ledgerRows } = await client.query(
    `INSERT INTO referral_ledger
       (edge_id, referrer_type, referrer_id, source, source_ref_id,
        base_amount, pct, amount, payout_status)
     VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 'pending')
     ON CONFLICT (source, source_ref_id) DO NOTHING
     RETURNING *`,
    [
      edge.id, edge.referrer_type, edge.referrer_id, source, sourceRefId,
      base, round2(pct), amount,
    ]
  );
  if (!ledgerRows[0]) return null; // already accrued for this event — idempotent

  let ledger = ledgerRows[0];

  // Settlement — credit the referrer's wallet inline + mark the ledger row
  // 'paid'. Both referrer types now have a wallet (influencers since launch;
  // agencies since Contract 3a), so accrual settles immediately ("if we earn,
  // they earn"). The target table is the only difference.
  const walletTable =
    edge.referrer_type === 'influencer' ? 'influencers' :
    edge.referrer_type === 'agency'     ? 'agencies'    : null;

  if (walletTable) {
    const credited = await client.query(
      `UPDATE ${walletTable}
          SET wallet_balance        = wallet_balance        + $1,
              referral_earned_total = referral_earned_total + $1
        WHERE id = $2`,
      [amount, edge.referrer_id]
    );
    // Only mark the row 'paid' if the referrer's wallet was actually credited.
    // If the referrer row is missing (rowCount 0), leave it 'pending' — no
    // silent loss; a later settlement can still pay it idempotently.
    if (credited.rowCount === 1) {
      const { rows: paidRows } = await client.query(
        `UPDATE referral_ledger
            SET payout_status = 'paid', paid_at = now()
          WHERE id = $1
          RETURNING *`,
        [ledger.id]
      );
      ledger = paidRows[0];
    }
  }

  return ledger;
}

/**
 * Accrue in the service's OWN transaction. Best-effort: any error is logged and
 * swallowed so the caller's host money path is never broken. Used by the
 * subscription webhook (after the invoice commits) and the commission-confirm
 * cron (autocommit host).
 */
async function accrue(opts) {
  try {
    return await db.withTransaction((client) => _accrueOnClient(client, opts));
  } catch (err) {
    console.error(
      `[referral] accrue failed (source=${opts && opts.source} ref=${opts && opts.sourceRefId}) — ` +
      `host path unaffected:`, err && err.message
    );
    return null;
  }
}

/**
 * Accrue INSIDE a host transaction, isolated by a SAVEPOINT so an accrual error
 * rolls back only the referral work — the host transaction (e.g. an escrow
 * tranche release) still commits. Used by escrow.service.processTrancheRelease.
 */
async function accrueWithClient(client, opts) {
  try {
    await client.query('SAVEPOINT referral_accrue');
    const ledger = await _accrueOnClient(client, opts);
    await client.query('RELEASE SAVEPOINT referral_accrue');
    return ledger;
  } catch (err) {
    try { await client.query('ROLLBACK TO SAVEPOINT referral_accrue'); } catch (_) { /* noop */ }
    try { await client.query('RELEASE SAVEPOINT referral_accrue'); } catch (_) { /* noop */ }
    console.error(
      `[referral] accrueWithClient failed (source=${opts && opts.source} ref=${opts && opts.sourceRefId}) — ` +
      `host transaction unaffected:`, err && err.message
    );
    return null;
  }
}

module.exports = {
  REFERRAL_WINDOW_MONTHS,
  round2,
  getOrCreateCode,
  lookupCode,
  resolveActiveEdge,
  createEdge,
  accrue,
  accrueWithClient,
};
